text(await tools.apply_patch("*** Begin Patch
*** Update File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s087/ehlikitap-images.sol.max.session-20261005/sec5/verdicts.jsonl
@@
+{"connection_id":"BC-631a77fdcdf9f7f30a06","ref":"SBLGNT:Luke.20.36","status":"rejected","reason":"The resurrected's inability to die contrasts with the condemned in Q 87:13, but ¶22 uses 'great' as an age-root note and does not compare final populations.","paragraphs":[],"evidence":["SBLGNT:Luke.20.36"],"annotations":[]}
+{"connection_id":"BC-3a2a43353099f21bf139","ref":"SBLGNT:Mark.4.28","status":"rejected","reason":"The stalk-ear-grain sequence is a crop parable, not human fetal growth; 1 Corinthians 15 supplies the crop/body bridge explicitly.","paragraphs":[],"evidence":["SBLGNT:Mark.4.28"],"annotations":[]}
+{"connection_id":"BC-cb6458abd55763ce2a8d","ref":"SBLGNT:Mark.4.29","status":"rejected","reason":"Harvest ends the crop parable but adds no bodily formation or resurrection claim to ¶22-23's paired images.","paragraphs":[],"evidence":["SBLGNT:Mark.4.29"],"annotations":[]}
+{"connection_id":"BC-d8321061213ecf0cf32d","ref":"SBLGNT:Mark.8.36","status":"rejected","reason":"Gaining the world and losing one's life is an apt worldly-life warning, but it has no formed-body or drying-pasture detail beyond ¶23's existing ethical conclusion.","paragraphs":[],"evidence":["SBLGNT:Mark.8.36"],"annotations":[]}
+{"connection_id":"BC-23fe73e149d526655a94","ref":"SBLGNT:Mark.9.48","status":"rejected","reason":"Mark repeats Isaiah 66:24's worm/fire formula; neither text states the condemned neither die nor live as Q 87:13 does, and the source is peripheral to ¶22-23's bodily argument.","paragraphs":[],"evidence":["SBLGNT:Mark.9.48"],"annotations":[]}
+{"connection_id":"BC-4fbd9061db6e4cc8b710","ref":"SBLGNT:Matt.6.20","status":"rejected","reason":"Heavenly treasure resisting decay is an ethical property image, not a human body/grass comparison or womb-to-age sequence.","paragraphs":[],"evidence":["SBLGNT:Matt.6.20"],"annotations":[]}
+{"connection_id":"BC-d5b5a6ac4731a9a9fe72","ref":"SBLGNT:Matt.6.27","status":"rejected","reason":"Greek ἡλικία is present, contrary to the wording flag, but the stature/lifespan ambiguity and anxiety setting do not establish ¶22's claim about bodily proportion or an allotted life span.","paragraphs":[],"evidence":["SBLGNT:Matt.6.27"],"annotations":[]}
+{"connection_id":"BC-43ccf7d6abb6b54d16ff","ref":"SBLGNT:Matt.6.27","status":"rejected","reason":"Reading ἡλικία as lifespan is possible but not secured by this verse's cubit image; Psalm 139:16 gives the measured-days link without that ambiguity.","paragraphs":[],"evidence":["SBLGNT:Matt.6.27"],"annotations":[]}
+{"connection_id":"BC-896ff4a96e7a3456f412","ref":"SBLGNT:Matt.6.30","status":"rejected","reason":"The grass burned tomorrow supports divine care amid anxiety, not the human body's mortality; Isaiah 40 supplies the latter explicit comparison.","paragraphs":[],"evidence":["SBLGNT:Matt.6.30"],"annotations":[]}
+{"connection_id":"BC-e13b9931a68442faae30","ref":"SBLGNT:Matt.6.30","status":"rejected","reason":"The same grass/oven image is concrete, but Matthew's application is clothing and trust; it does not extend ¶23's body-to-resurrection reasoning.","paragraphs":[],"evidence":["SBLGNT:Matt.6.30"],"annotations":[]}
+{"connection_id":"BC-879142e2e7b8beee584b","ref":"SBLGNT:Phil.3.21","status":"rejected","reason":"Christ's transformation of the lowly body is explicit but is another Christian answer to future embodiment after 1 Corinthians 15's more developed seed/body passage.","paragraphs":[],"evidence":["SBLGNT:Phil.3.21"],"annotations":[]}
+{"connection_id":"BC-eefdef7b3ff22991c70c","ref":"SBLGNT:Phil.3.21","status":"rejected","reason":"The same transformed-body claim is valid yet adds no vegetation or prenatal formation to the selected 1 Corinthians 15 treatment at ¶23.","paragraphs":[],"evidence":["SBLGNT:Phil.3.21"],"annotations":[]}
